"""In this code we check a random number generated by the builtin function
checking is it armstrong or not."""
import random
t=0
var=random.randint(100,9999)
print(var)
power=len(str(var))
varr=var
while var!=0:
    a=var%10
    t=t+a**power
    var=var//10
if t==varr:
    print(f"{varr} Its a armstrong number")
else:
    print(f"{varr} Not an armstrong")